package com.g4t0xx.forge;
import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Actual local image/video diffusion, with private verified models and durable jobs. */
final class MediaStudio {
 private static MediaStudio instance;static synchronized MediaStudio get(Context c){if(instance==null)instance=new MediaStudio(c.getApplicationContext());return instance;}
 final Context ctx;final File models,output,jobsFile;final ExecutorService queue=Executors.newSingleThreadExecutor();JSONArray jobs=new JSONArray();volatile java.lang.Process process;volatile String status="Pronto";volatile boolean busy;
 MediaStudio(Context c){ctx=c;models=new File(c.getFilesDir(),"media-models");output=new File(c.getFilesDir(),"workspace/media");jobsFile=new File(c.getFilesDir(),"media-jobs.json");models.mkdirs();output.mkdirs();try{if(jobsFile.exists()){jobs=new JSONArray(Json.read(new FileInputStream(jobsFile),4*1024*1024));for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if(Arrays.asList("queued","running").contains(j.optString("status"))){j.put("status","interrupted");j.put("error","Processo reiniciado. Arquivos e parâmetros preservados.");}}save();}}catch(Exception ignored){}}
 synchronized void save()throws Exception{Json.atomic(jobsFile,jobs.toString());}
 JSONArray manifest()throws Exception{return new JSONArray(Json.read(ctx.getAssets().open("media-models.json"),100000));}
 synchronized JSONObject info()throws Exception{JSONArray specs=manifest();for(int i=0;i<specs.length();i++){JSONObject m=specs.getJSONObject(i);File f=new File(models,m.getString("file"));m.put("installed",f.exists()&&f.length()==m.getLong("size"));}return Json.obj("models",specs,"jobs",new JSONArray(jobs.toString()),"busy",busy,"status",status,"runtime",new File(ctx.getApplicationInfo().nativeLibraryDir,"libforge_sd.so").exists());}
 synchronized File file(String id)throws Exception{if(!id.matches("[a-zA-Z0-9._-]+"))throw new IOException("Arquivo inválido");File f=new File(output,id).getCanonicalFile();if(!f.toPath().startsWith(output.getCanonicalFile().toPath())||!f.exists())throw new IOException("Arquivo não encontrado");return f;}
 synchronized JSONObject submit(JSONObject a)throws Exception{
  if(busy)throw new IOException("Aguarde a geração ou instalação atual");String kind=a.optString("kind","image");if(!kind.equals("image")&&!kind.equals("video"))throw new IOException("Escolha imagem ou vídeo");String prompt=a.getString("prompt").trim();if(prompt.isEmpty()||prompt.length()>6000)throw new IOException("Descreva a imagem ou vídeo");
  JSONObject j=new JSONObject(a.toString()).put("id",UUID.randomUUID().toString()).put("kind",kind).put("status","queued").put("created",System.currentTimeMillis());jobs.put(j);save();busy=true;AgentService.begin(ctx);queue.submit(()->generate(j));return Json.obj("id",j.getString("id"));
 }
 void generate(JSONObject j){PowerManager.WakeLock wake=ctx.getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"forge:media");wake.acquire(55*60*1000L);try{
  Assistant.get(ctx).engine.stop();j.put("status","running");save();String kind=j.getString("kind");boolean light=kind.equals("video")&&j.optString("mode","image_motion").equals("image_motion");JSONArray specs=manifest();for(int i=0;i<specs.length();i++){JSONObject m=specs.getJSONObject(i);if(m.getString("kind").equals(light?"image":kind)){File f=new File(models,m.getString("file"));if(!f.exists()||f.length()!=m.getLong("size"))throw new IOException("Instale os modelos de "+kind+" no estúdio antes de gerar");}}
  int w=j.optInt("width",512),h=j.optInt("height",512);if(w<64||h<64||w>4096||h>4096||w%64!=0||h%64!=0)throw new IOException("Largura e altura devem ser múltiplos de 64 entre 64 e 4096");int steps=j.optInt("steps",kind.equals("image")?2:8);if(steps<1||steps>100)throw new IOException("Etapas devem ficar entre 1 e 100");
  String filename=j.getString("id")+(kind.equals("image")?".png":light?".mp4":".webm");File dest=new File(output,filename);File rendered=light?new File(output,j.getString("id")+"-source.png"):dest;List<String> args=new ArrayList<>(Arrays.asList(ctx.getApplicationInfo().nativeLibraryDir+"/libforge_sd.so","-p",j.getString("prompt"),"-W",String.valueOf(w),"-H",String.valueOf(h),"--steps",String.valueOf(steps),"--threads",String.valueOf(ctx.getSharedPreferences("assistant",0).getInt("threads",3)),"--seed",String.valueOf(j.optLong("seed",42)),"--sampling-method","euler","--vae-tiling","-o",rendered.getAbsolutePath()));
  if(j.optBoolean("disk",true))args.addAll(Arrays.asList("--params-backend","disk","--mmap","--disable-prefetch","--max-vram","0.5","--batched-cfg","off"));if(kind.equals("image")||light){args.addAll(Arrays.asList("-m",new File(models,"sd_turbo-f16-q8_0.gguf").getAbsolutePath(),"--cfg-scale","1"));}else{int frames=j.optInt("frames",17);if(frames<5||frames>257||(frames-1)%4!=0)throw new IOException("Vídeo: quantidade de quadros deve ser 4n+1 (5, 9, 17, 33...)");args.addAll(Arrays.asList("-M","vid_gen","--diffusion-model",new File(models,"Wan2.1-T2V-1.3B-Q4_K_M.gguf").getAbsolutePath(),"--t5xxl",new File(models,"umt5-xxl-encoder-Q3_K_M.gguf").getAbsolutePath(),"--vae",new File(models,"wan_2.1_vae.safetensors").getAbsolutePath(),"--video-frames",String.valueOf(frames),"--fps",String.valueOf(j.optInt("fps",16)),"--cfg-scale","6","--flow-shift","3"));}
  status="Gerando "+(kind.equals("image")?"imagem":"vídeo")+" neste Android";File log=new File(ctx.getFilesDir(),"media-"+j.getString("id")+".log");process=new ProcessBuilder(args).redirectErrorStream(true).redirectOutput(log).start();boolean ended=process.waitFor(50,TimeUnit.MINUTES);if(!ended){process.destroy();throw new IOException("Geração excedeu 50 minutos; parâmetros preservados");}if(process.exitValue()!=0||!rendered.exists()||rendered.length()<100)throw new IOException("Motor de geração encerrou ("+process.exitValue()+"). Selecione resolução menor ou confira modelos e memória.");if(light){int frames=j.optInt("frames",17),fps=j.optInt("fps",8);if(frames<5||frames>257||fps<1||fps>60)throw new IOException("Quadros ou FPS invalidos");status="Animando imagem local e codificando MP4";LocalVideo.create(rendered,dest,w,h,frames,fps);j.put("mode","image_motion");}j.put("status","done");j.put("file",filename);j.put("bytes",dest.length());j.put("url","https://forge.local/media/"+filename);save();status="Geração concluída";
 }catch(Exception e){try{j.put("status","failed");j.put("error",e.getMessage());save();status=e.getMessage();}catch(Exception ignored){}}finally{process=null;busy=false;if(wake.isHeld())wake.release();AgentService.finished(ctx);}}
 synchronized void install(String kind)throws Exception{if(busy)throw new IOException("Outra geração está ativa");if(ctx.getSharedPreferences("assistant",0).getBoolean("offline",false))throw new IOException("Desative modo offline para baixar modelos; depois eles funcionam sem rede");busy=true;AgentService.begin(ctx);queue.submit(()->{try{JSONArray list=manifest();for(int i=0;i<list.length();i++){JSONObject m=list.getJSONObject(i);if(m.getString("kind").equals(kind))download(m);}status="Modelos instalados e verificados";}catch(Exception e){status="Instalação falhou: "+e.getMessage();}finally{busy=false;AgentService.finished(ctx);}});}
 void download(JSONObject m)throws Exception{File dest=new File(models,m.getString("file"));long size=m.getLong("size");if(dest.exists()&&dest.length()==size)return;if(models.getFreeSpace()<size+300000000L)throw new IOException("Armazenamento insuficiente");File part=new File(dest.getPath()+".part");URL url=new URL(m.getString("url"));HttpURLConnection c=null;try{for(int i=0;i<8;i++){if(!url.getProtocol().equals("https"))throw new IOException("Download exige HTTPS");c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(30000);c.setReadTimeout(60000);int code=c.getResponseCode();if(code==200)break;if(code>=300&&code<400){String next=c.getHeaderField("Location");c.disconnect();url=new URL(url,next);continue;}throw new IOException("Download HTTP "+code);}if(c==null||c.getResponseCode()!=200)throw new IOException("Não foi possível baixar");java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");long done=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(part)){byte[] b=new byte[262144];int n;while((n=in.read(b))!=-1){done+=n;if(done>size)throw new IOException("Tamanho inesperado");out.write(b,0,n);hash.update(b,0,n);status=m.getString("file")+": "+done*100/size+"%";}out.getFD().sync();}StringBuilder h=new StringBuilder();for(byte b:hash.digest())h.append(String.format("%02x",b));if(done!=size||!h.toString().equals(m.getString("sha256")))throw new IOException("Verificação do modelo falhou");Files.move(part.toPath(),dest.toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{if(c!=null)c.disconnect();if(part.exists())part.delete();}}
 synchronized void stop(){if(process!=null)process.destroyForcibly();status="Pausa solicitada";}
}
